package android.content;import android.app.AlarmManager;import android.os.PowerManager;public class Context {public static final String ALARM_SERVICE="alarm",POWER_SERVICE="power";public final AlarmManager alarm=new AlarmManager();public final PowerManager power=new PowerManager();public BroadcastReceiver receiver;public int receiverFlags=-1;public Context getApplicationContext(){return this;}public Object getSystemService(String n){return n.equals(ALARM_SERVICE)?alarm:power;}public String getPackageName(){return "com.tencent.mm";}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f){receiver=r;receiverFlags=0;return null;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,int flags){receiver=r;receiverFlags=flags;return null;}}
